create table if not exists profiles(id uuid primary key,username text unique not null,tokens bigint not null default 0,score bigint not null default 0,hammer_level int not null default 1,referrals int not null default 0,created_at timestamptz default now());
create table if not exists secret_codes(code text primary key,reward bigint not null,max_claims int not null default 1,claims int not null default 0,active boolean not null default true,expires_at timestamptz);
create table if not exists code_claims(id bigint generated by default as identity primary key,user_id uuid not null,code text references secret_codes(code),created_at timestamptz default now(),unique(user_id,code));
create table if not exists leaderboard_scores(user_id uuid primary key,score bigint not null default 0,updated_at timestamptz default now());
create table if not exists referrals(id bigint generated by default as identity primary key,referrer_id uuid not null,referred_id uuid not null unique,status text not null default 'pending',created_at timestamptz default now());
-- Enable Row Level Security and add least-privilege policies before production.
